WITH filtered AS (SELECT *, COALESCE(amount, 0) AS amount_filled, ROUND(amount * 1.07, 2) AS amount_scaled FROM payments WHERE paid_at > TIMESTAMP '2023-10-02 20:00:00'), enriched AS (SELECT *, SUM(amount_scaled) OVER (PARTITION BY status ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_scaled_sum_30d, LEAD(amount_filled, 1, 0) OVER (ORDER BY paid_at, id) AS next_amount_filled, COUNT(amount_filled) OVER (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS amount_filled_count_90d FROM filtered), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM enriched), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged), enriched_payments AS (SELECT id, order_id, method, amount_filled, is_new_session, LEAD(amount_filled, 1) OVER (PARTITION BY status ORDER BY amount_scaled, id) AS next_amount_filled_2, STDDEV_SAMP(burst_id) OVER (PARTITION BY method) AS method_stddev_samp_burst_id, ROW_NUMBER() OVER (PARTITION BY method ORDER BY is_new_session DESC, id) AS event_seq FROM islands) SELECT method_stddev_samp_burst_id, MAX(event_seq) FILTER (WHERE method = 'card') AS card_max_event_seq, ROUND(AVG(amount_filled), 2) AS avg_amount_filled, SORT_ARRAY(COLLECT_SET(method)) AS method_list FROM enriched_payments GROUP BY method_stddev_samp_burst_id ORDER BY avg_amount_filled NULLS FIRST;
